import {World} from './world.js';
import {WORDS,REGIONS,ACHIEVEMENTS,getWord} from './data.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const ICONS={sound:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M11 4 5 9H2v6h3l6 5V4Z"/><path d="M15 8q5 4 0 8m3-11q8 7 0 14"/></svg>',mute:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M11 4 5 9H2v6h3l6 5V4Z"/><path d="m16 9 6 6m0-6-6 6"/></svg>',help:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 2.5"/><path d="M12 16v1"/></svg>',settings:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2.5" fill="#f5f5ed"/><circle cx="15" cy="17" r="2.5" fill="#f5f5ed"/></svg>'};
const SAVE='lingua-expedition-v1';
const fresh=()=>({version:1,region:0,unlocked:0,evidence:{},hypotheses:{},verified:[],completed:[],relics:[],garden:false,pronouns:false,ending:false,sound:false,started:Date.now(),elapsed:0,attempts:0});
let state=fresh(),saveAvailable=true;try{const saved=JSON.parse(localStorage.getItem(SAVE));if(saved?.version===1){state={...fresh(),...saved};state.region=Math.max(0,Math.min(3,Number(state.region)||0));state.unlocked=Math.max(0,Math.min(3,Number(state.unlocked)||0));state.evidence=typeof state.evidence==='object'&&state.evidence?state.evidence:{};['verified','completed','relics'].forEach(k=>{if(!Array.isArray(state[k]))state[k]=[]})}}catch{};
let world,tab='words',currentObservation=null,observationBeat=0,toastTimer,modalCloser=null,sessionStart=Date.now(),audioContext,ambientNodes=[],lastFocus=null;
const evidenceTotal=()=>Object.values(state.evidence).reduce((a,b)=>a+(Array.isArray(b)?b.length:0),0);
const region=()=>REGIONS[state.region];
const save=()=>{try{localStorage.setItem(SAVE,JSON.stringify({...state,elapsed:state.elapsed+Math.floor((Date.now()-sessionStart)/1000)}))}catch{saveAvailable=false}};
const tone=(n=0,type='word')=>{if(!state.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const now=audioContext.currentTime;const notes=type==='success'?[0,4,7,12]:type==='error'?[2,0]:[n%12,(n+7)%12];notes.forEach((note,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=220*Math.pow(2,note/12);gain.gain.setValueAtTime(0,now+i*.12);gain.gain.linearRampToValueAtTime(.055,now+i*.12+.025);gain.gain.exponentialRampToValueAtTime(.001,now+i*.12+.7);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.12);osc.stop(now+i*.12+.8)})}catch{}};
function ambient(){if(!state.sound){ambientNodes.forEach(n=>n.stop());ambientNodes=[];return}try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();if(ambientNodes.length)return;[73.416,110,146.832].forEach((f,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.value=.009-i*.002;osc.connect(gain);gain.connect(audioContext.destination);osc.start();ambientNodes.push(osc)})}catch{}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function closeModal(){if(modalCloser)modalCloser();modalCloser=null;$('#modal-root').innerHTML='';world?.setInputBlocked(false);lastFocus?.focus?.()}
function modal(content,{large=false,closeable=true}={}){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="田野手记">${closeable?'<button class="close-button" id="modal-close" aria-label="关闭">×</button>':''}${content}</section></div>`;world?.setInputBlocked(true);$('#modal-close')?.addEventListener('click',closeModal);$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop')&&closeable)closeModal()});$('.modal button, .modal input, .modal select')?.focus();}
function achieved(id){return {observer:evidenceTotal()>0,linguist:state.verified.length>=3,archivist:evidenceTotal()===24,relics:state.relics.length===4,gardener:state.garden,ambassador:state.ending}[id]}
function updateUI(){const r=region();$('#chapter-num').textContent=`CHAPTER 0${r.id+1}`;$('#chapter-title').textContent=r.title;$('#chapter-subtitle').textContent=r.subtitle;$('#coordinate').textContent=r.coord;$('#day-label').textContent=`DAY 0${r.id+1}`;$('#weather-text').innerHTML=`${r.weather}<small>${r.season}</small>`;$('#scene-caption-text').textContent=`${r.name} · ${state.completed.includes(r.id)?'已建立联系':'勘察中'}`;$('#word-count').textContent=Object.keys(state.evidence).length;$('#mobile-count').textContent=`${state.verified.length}/12`;$('#evidence-count').textContent=evidenceTotal();const percent=Math.round(state.verified.length/12*100);$('#understanding').innerHTML=`${percent}<span>%</span>`;$('#understanding-fill').style.width=percent+'%';$('#sound-toggle').innerHTML=state.sound?ICONS.sound:ICONS.mute;$('#sound-toggle').title=state.sound?'关闭声音':'开启声音';$('#sound-toggle').setAttribute('aria-label',state.sound?'关闭声音':'开启声音');
 const count=r.words.reduce((a,id)=>a+(state.evidence[id]?.length||0),0),verified=r.words.every(id=>state.verified.includes(id));$('#objective-text').textContent=state.ending?'语言让两个世界彼此靠近':state.completed.includes(r.id)?r.id===3?'重现四步迎客仪式':'这段交流已完成，继续前往下一站':verified?'用理解的词语，向居民表达意图':r.mission;$('#objective-detail').textContent=verified?'点击遗迹标记，组合一句完整的话':count===6?'线索已齐全 · 在词典中验证三词':`行为证据 ${count} / 6 · 已破译 ${r.words.filter(id=>state.verified.includes(id)).length} / 3`;$('#objective-progress-fill').style.width=`${count/6*100}%`;
 $('#chapter-nav').innerHTML=REGIONS.map((rg,i)=>`<button class="chapter-step ${i===state.region?'current':''} ${state.completed.includes(i)?'done':''}" data-region="${i}" ${i>state.unlocked?'disabled':''} aria-label="${rg.name}${i>state.unlocked?'，尚未解锁':''}"><span>${state.completed.includes(i)?'✓':i>state.unlocked?'·':'0'+(i+1)}</span><div><strong>${rg.name}</strong><small>${i===state.region?'YOU ARE HERE':i>state.unlocked?'UNEXPLORED':state.completed.includes(i)?'TRANSLATED':'DISCOVERED'}</small></div></button>`).join('');$$('[data-region]').forEach(b=>b.addEventListener('click',()=>travel(Number(b.dataset.region))));renderJournal();world?.setSolved(state.completed.includes(r.id));world?.setEvidence(state.evidence,state.verified,state.relics);world?.setCompanion(state.completed.includes(2));if(world)world.companion.material.color.setHex(state.garden?0xffd684:0xd6fac1);save();}
function renderJournal(){const r=region();$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='evidence'){const entries=WORDS.flatMap(w=>(state.evidence[w.id]||[]).map(i=>({w,i})));$('#journal-content').innerHTML=entries.length?entries.reverse().map(({w,i})=>`<article class="note-entry"><div class="note-meta"><span class="note-rune">${w.glyph}</span> ${w.site} · 观察 0${i+1}</div><p>${w.clues[i]}</p></article>`).join(''):'<div class="empty-note"><span>⌕</span><div>观察手记还是空白。<br>点击世界中的观察标记，记录居民的动作与语境。</div></div>';return}
 const card=id=>{const w=getWord(id),seen=!!state.evidence[id],known=state.verified.includes(id),guess=state.hypotheses[id];return `<button class="word-card ${!seen?'locked':known?'verified':guess?'guessed':''}" data-word="${id}"><span class="rune">${w.glyph}</span><span class="word-info"><strong>${known?w.meaning:guess?guess+'？':seen?'等待你的推断':'尚未解读'}</strong><small>${known?'已通过语境验证':seen?`已记录 ${state.evidence[id].length}/2 条线索`:'寻找这个符号的语境'}</small></span><span class="word-status">${known?'✓':seen?'＋':'·'}</span></button>`};
 const isVerified=r.words.every(id=>state.verified.includes(id));$('#journal-content').innerHTML=`<div class="word-section-head"><span>本地语言 · 第 ${r.id+1} 组</span><span>${r.words.filter(id=>state.verified.includes(id)).length} / 03</span></div>${r.words.map(card).join('')}${isVerified?`<div class="region-complete">✓ 三个符号已得到证据支持。<br>${state.completed.includes(r.id)?'你已经用它们建立了联系。':'试着按居民的语序组织一句话。'}<button class="validate-button" id="communicate">${state.completed.includes(r.id)?r.id===3?'完成迎客仪式':'继续旅程':'组合句子 · 建立交流'}</button></div>`:`<div class="empty-note"><span>✧</span><div>同一个符号，至少观察两次。<br>记录线索后，点击符号提出词义假设。</div></div><button class="validate-button" id="validate-open" ${r.words.every(id=>(state.evidence[id]?.length||0)===2&&state.hypotheses[id])?'':'disabled'}>验证这组三个词义</button><p class="settings-info">${r.words.every(id=>(state.evidence[id]?.length||0)===2)?'看完整段行为，检验你的理解。':'收集 6 条证据，并为三个符号提出假设。'}</p>`}${state.verified.some(id=>!r.words.includes(id))?`<div class="word-section-head" style="margin-top:26px"><span>已确认的其他词语</span><span>${state.verified.filter(id=>!r.words.includes(id)).length}</span></div>${state.verified.filter(id=>!r.words.includes(id)).map(card).join('')}`:''}`;
 $$('[data-word]').forEach(b=>b.addEventListener('click',()=>openWord(b.dataset.word)));$('#validate-open')?.addEventListener('click',openValidation);$('#communicate')?.addEventListener('click',openDialogue);
}
function observe(id){closeModal();$('#journal').classList.remove('open');currentObservation=id;observationBeat=(state.evidence[id]||[]).includes(0)?(state.evidence[id]||[]).includes(1)?0:1:0;world?.observe(id);renderObservation();tone(WORDS.findIndex(w=>w.id===id));}
function renderObservation(){const w=getWord(currentObservation);if(!w)return;world?.setObservationBeat(observationBeat);const collected=state.evidence[w.id]||[],all=collected.length===2;$('#observation').classList.remove('hidden');$('#observation').innerHTML=`<button class="close-button" id="observation-close" aria-label="结束观察">×</button><div class="panel-kicker">OBSERVATION 0${observationBeat+1} / 02</div><h2 id="observation-title">${w.site}</h2><p class="observation-subtitle">${w.role} · 观察动作与语境</p><div class="utterance">${region().words.map(id=>`<span class="rune ${id===w.id?'target-rune':''}">${getWord(id).glyph}</span>`).join('')}<button class="sound-button" id="play-utterance" aria-label="聆听外星语">${ICONS.sound}</button></div><p class="scene-text">${w.clues[observationBeat]}</p><div class="observation-footer"><div class="evidence-dots">${[0,1].map(i=>`<i class="${collected.includes(i)?'collected':''}"></i>`).join('')}</div><button class="text-button" id="replay-observation">${all?'另一个语境':'重演动作'}</button><button class="primary" id="record-evidence">${all?'提出词义假设':collected.includes(observationBeat)?'下一条线索':'记录这条线索'}</button></div>`;$('#observation-close').onclick=closeObservation;$('#play-utterance').onclick=()=>{if(!state.sound){state.sound=true;ambient();updateUI()}tone(WORDS.findIndex(q=>q.id===w.id))};$('#replay-observation').onclick=()=>{if(all)observationBeat=1-observationBeat;world?.observe(w.id);renderObservation();tone(observationBeat+2)};$('#record-evidence').onclick=()=>{if(all){closeObservation();openWord(w.id);return}state.evidence[w.id]??=[];if(!state.evidence[w.id].includes(observationBeat)){state.evidence[w.id].push(observationBeat);tone(4);toast(`已记录线索 · ${w.glyph} ${state.evidence[w.id].length}/2`)}if(state.evidence[w.id].length===1)observationBeat=1;renderObservation();updateUI()};}
function closeObservation(){currentObservation=null;$('#observation').classList.add('hidden');world?.stopObserve()}
function openWord(id){const w=getWord(id);if(!state.evidence[id]){toast(`先前往「${w.site}」观察符号 ${w.glyph}`);if(region().words.includes(id)){observe(id)}return}closeObservation();let selected=state.hypotheses[id]||null;const known=state.verified.includes(id);modal(`<div class="panel-kicker">LEXICON / ${known?'VERIFIED':'HYPOTHESIS'}</div><div class="word-modal-head"><div class="large-rune">${w.glyph}</div><div><h2>${known?w.meaning:'这个符号意味着什么？'}</h2><small>${known?'已通过语境验证':`来自 ${w.site}`}</small></div></div><div class="section-label"><span>你记录的证据</span><span>${state.evidence[id].length} / 2</span></div>${[0,1].map(i=>state.evidence[id].includes(i)?`<div class="clue"><small>CONTEXT 0${i+1}</small>${w.clues[i]}</div>`:`<div class="clue missing">尚缺另一种语境。回到观察点，收集第二条线索。</div>`).join('')}${known?'<div class="hint-text">这个词已在新的行为语境中得到验证，可以放心用来交流。</div>':`<div class="section-label"><span>提出词义假设</span><button class="text-button" id="word-hint">给我一点提示</button></div><div class="meaning-options">${w.options.map(m=>`<button class="meaning-option ${selected===m?'selected':''}" data-meaning="${m}">${m}</button>`).join('')}</div><div id="word-hint-text"></div><div class="modal-actions"><button class="secondary" id="back-observe">继续观察</button><button class="primary" id="save-hypothesis" ${selected?'':'disabled'}>记下这个假设</button></div>`}`);
 $$('[data-meaning]').forEach(b=>b.onclick=()=>{selected=b.dataset.meaning;$$('[data-meaning]').forEach(el=>el.classList.toggle('selected',el===b));$('#save-hypothesis').disabled=false});$('#word-hint')?.addEventListener('click',()=>{$('#word-hint-text').innerHTML=`<p class="hint-text">${w.tip}</p>`});$('#back-observe')?.addEventListener('click',()=>{closeModal();if(region().words.includes(id))observe(id)});$('#save-hypothesis')?.addEventListener('click',()=>{if(!selected)return;state.hypotheses[id]=selected;closeModal();updateUI();toast(`已提出假设：${w.glyph} 可能表示「${selected}」`);if(region().words.every(k=>state.hypotheses[k]&&(state.evidence[k]?.length||0)===2))setTimeout(()=>toast('三个假设已齐全。点击词典底部的「验证」进行检验。'),1200)});
}
function openValidation(){const r=region();if(!r.words.every(id=>(state.evidence[id]?.length||0)===2&&state.hypotheses[id]))return;closeObservation();modal(`<div class="panel-kicker">FIELD EXPERIMENT / 0${r.id+1}</div><h2>让语境检验你的理解</h2><p class="intro">${r.challenge}</p><div class="sentence-slots">${r.words.map(id=>`<div class="sentence-slot filled"><span class="rune">${getWord(id).glyph}</span><small>${state.hypotheses[id]}？</small></div>`).join('')}</div><div class="grammar-note">留意居民说话的顺序：<br>先指向引起变化的人或事物，再指向变化的对象，最后演示动作。</div><div class="feedback" id="validation-feedback" role="status"></div><div class="modal-actions"><button class="secondary" id="revise">返回调整假设</button><button class="primary" id="validate-now">检验三个词义</button></div>`);$('#revise').onclick=closeModal;$('#validate-now').onclick=()=>{state.attempts++;const correct=r.words.filter(id=>state.hypotheses[id]===getWord(id).meaning).length;if(correct===3){r.words.forEach(id=>{if(!state.verified.includes(id))state.verified.push(id)});tone(0,'success');updateUI();$('#validation-feedback').classList.add('success');$('#validation-feedback').textContent='三项假设全部与行为吻合。你第一次听懂了这一段话。';$('#validate-now').textContent='试着与居民交流';$('#validate-now').onclick=()=>{closeModal();openDialogue()};$('#revise').style.display='none';}else{tone(0,'error');$('#validation-feedback').textContent=`${correct} / 3 项与行为吻合。${correct?'保留有证据支持的假设，再检查其余词义。':'回想物品改变、角色互换时，哪些含义仍然成立。'} 可以返回词典查看提示。`;save();}};
}
function openDialogue(){const r=region();closeObservation();if(!r.words.every(id=>state.verified.includes(id))){toast('先收集线索，并在词典中验证这组三个词。');return}if(state.completed.includes(r.id)){if(r.id===3){state.ending?showEnding():openRitual();return}travelPrompt();return}let sentence=[];const bank=[r.sentence[2],r.sentence[0],r.sentence[1]];modal(`<div class="panel-kicker">FIRST CONTACT / 0${r.id+1}</div><h2>让他们听懂你的话</h2><p class="intro">${r.goal}</p><div class="grammar-note">当地语序：引起变化者 · 变化对象 · 动作<br>点击下方符号，依次放入。点击已放入的符号可撤回。</div><div class="sentence-slots" id="sentence-slots"></div><div class="sentence-bank" id="sentence-bank"></div><div class="feedback" id="sentence-feedback" role="status"></div><div class="modal-actions"><button class="secondary" id="sentence-reset">清空重组</button><button class="primary" id="sentence-submit" disabled>说出这句话</button></div>`);
 function render(){const labels=['引起变化者','变化对象','动作'];$('#sentence-slots').innerHTML=[0,1,2].map(i=>`<button class="sentence-slot ${sentence[i]?'filled':''}" data-slot="${i}" aria-label="${sentence[i]?'撤回'+getWord(sentence[i]).meaning:labels[i]}">${sentence[i]?`<span class="rune">${getWord(sentence[i]).glyph}</span><small>${getWord(sentence[i]).meaning}</small>`:`<span>0${i+1}</span><small>${labels[i]}</small>`}</button>`).join('');$('#sentence-bank').innerHTML=bank.map(id=>`<button class="rune-button" data-token="${id}" ${sentence.includes(id)?'disabled':''}><span class="rune">${getWord(id).glyph}</span><small>${getWord(id).meaning}</small></button>`).join('');$$('[data-token]').forEach(b=>b.onclick=()=>{if(sentence.length<3){sentence.push(b.dataset.token);tone(WORDS.findIndex(w=>w.id===b.dataset.token));render();($('#sentence-bank button:not(:disabled)')||$('#sentence-submit')).focus()}});$$('[data-slot]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.slot);if(sentence[i]){sentence.splice(i,1);render();$('#sentence-bank button:not(:disabled)')?.focus()}});$('#sentence-submit').disabled=sentence.length!==3;}
 render();$('#sentence-reset').onclick=()=>{sentence=[];render();$('#sentence-feedback').textContent=''};$('#sentence-submit').onclick=()=>{if(sentence.join()===r.sentence.join()){state.completed.push(r.id);state.unlocked=Math.min(3,r.id+1);tone(0,'success');closeModal();updateUI();travelPrompt();}else{tone(0,'error');const msg=sentence[2]!==r.sentence[2]?'居民轻敲句尾的位置，再演示了一遍动作。也许动作需要放在最后。':r.id===0?'居民在沙地画出“一滴水正在喝一个小人”，随后困惑地摇头。再想想谁在做动作。':r.id===1?'园丁把种子摆成小人的模样，尝试让它递出你的画像。他似乎误解了行动者。':r.id===2?'反光板照向墙面，幼灯仍然沉睡。想想真正让生命苏醒的是什么。':'石镜投出一道“石门推开月亮”的影子。这和你想表达的因果相反。';$('#sentence-feedback').textContent=msg;}};
}
function travelPrompt(){const r=region();modal(`<div class="panel-kicker">CONNECTION ESTABLISHED</div><h2>${r.story} · 交流成功</h2><div class="utterance">${r.sentence.map(id=>`<span class="rune">${getWord(id).glyph}</span>`).join('')}</div><p class="intro" style="margin-top:22px">${r.success}</p><div class="hint-text">已获得：${r.inventory}<br>迎客礼记忆 ${state.completed.length} / 4 · ${state.completed.map(i=>REGIONS[i].story).join(' → ')}</div><div class="modal-actions"><button class="secondary" id="stay-region">继续探索这里</button><button class="primary" id="travel-next">${r.id===3?'重现迎客仪式':'前往'+REGIONS[r.id+1].name}</button></div>`);$('#stay-region').onclick=closeModal;$('#travel-next').onclick=()=>{closeModal();r.id===3?openRitual():travel(r.id+1)};}
function travel(index){if(index>state.unlocked||index<0||index>3)return;if(index===state.region){closeModal();return}closeModal();closeObservation();state.region=index;world?.buildRegion(index);updateUI();toast(`进入 ${region().name} · ${region().subtitle}`)}
function discoverRelic(){if(state.relics.includes(state.region))return;closeObservation();state.relics.push(state.region);tone(0,'success');updateUI();modal(`<div class="panel-kicker">CULTURAL ARTIFACT / 0${state.relics.length}</div><div class="ending-mark" style="margin-top:15px">✧</div><h2>${region().secret}</h2><p class="intro">${region().secretText}</p><div class="hint-text">已收藏 ${state.relics.length} / 4 件文明遗物。<br>${state.relics.length===4?'成就解锁：文明的侧面。':'每个区域都藏着一段不属于词典的故事。'}</div><div class="modal-actions"><button class="primary" id="relic-close">收入田野档案</button></div>`);$('#relic-close').onclick=closeModal;}
function openRitual(){if(state.completed.length!==4){toast('完成四个区域的交流，才能重现仪式。');return}closeObservation();let order=[];modal(`<div class="panel-kicker">THE WELCOMING RITUAL</div><h2>把四段记忆，连成一个故事</h2><p class="intro">壁画上没有新的词语。它只问：一个陌生人，是怎样一步步成为客人的？<br>按旅程中的先后顺序，选择四块记忆石片。</p><div class="sentence-slots" id="ritual-slots" style="gap:7px"></div><div class="sentence-bank" id="ritual-bank"></div><div class="feedback" id="ritual-feedback" role="status"></div><div class="modal-actions"><button class="secondary" id="ritual-reset">重新排列</button><button class="primary" id="ritual-submit" disabled>完成迎客仪式</button></div>`,{large:true});function render(){$('#ritual-slots').innerHTML=[0,1,2,3].map((_,i)=>`<button class="sentence-slot ${order[i]!==undefined?'filled':''}" data-ritual-slot="${i}">${order[i]!==undefined?`<span class="rune" style="font-size:26px">${getWord(REGIONS[order[i]].words[1]).glyph}</span><small>${REGIONS[order[i]].story}</small>`:`<span>0${i+1}</span><small>记忆石片</small>`}</button>`).join('');$('#ritual-bank').innerHTML=[2,0,3,1].map(i=>`<button class="rune-button" data-ritual="${i}" ${order.includes(i)?'disabled':''}><span class="rune" style="font-size:20px">${REGIONS[i].sentence.map(id=>getWord(id).glyph).join(' ')}</span><small>${REGIONS[i].story}</small></button>`).join('');$$('[data-ritual]').forEach(b=>b.onclick=()=>{order.push(Number(b.dataset.ritual));render();($('#ritual-bank button:not(:disabled)')||$('#ritual-submit')).focus()});$$('[data-ritual-slot]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.ritualSlot);if(order[n]!==undefined){order.splice(n,1);render();$('#ritual-bank button:not(:disabled)')?.focus()}});$('#ritual-submit').disabled=order.length!==4}render();$('#ritual-reset').onclick=()=>{order=[];render()};$('#ritual-submit').onclick=()=>{if(order.join()==='0,1,2,3'){state.ending=true;save();tone(0,'success');closeModal();updateUI();showEnding()}else{let correct=0;while(order[correct]===correct&&correct<4)correct++;const explanation=['仪式在共饮前停下了。客人需要先被接纳，才能开启交换。','空荡荡的灯台没有种子。要先接受园丁的赠予。','月光落在沉睡的幼灯上，没能抵达门廊。先让灯醒来。','现在，完整的迎客礼还缺最后一步：入门。'][correct];$('#ritual-feedback').textContent=`${explanation} 已保留前 ${correct} 步正确记忆。`;order=order.slice(0,correct);render();tone(0,'error')}};}
function showEnding(){const minutes=Math.max(1,Math.round((state.elapsed+(Date.now()-sessionStart)/1000)/60));modal(`<div class="ending"><div class="panel-kicker">EXPEDITION COMPLETE</div><div class="ending-mark">⟐</div><h2>原来，这里也叫「家」</h2><p class="ending-story">门后的居民没有欢呼。<br>他们只是再次把手放在胸口，<br>然后轻轻伸向你。<br>这一次，你听懂了。</p><div class="ending-stats"><div><strong>12</strong><span>破译词语</span></div><div><strong>${evidenceTotal()}</strong><span>行为证据</span></div><div><strong>${minutes}</strong><span>分钟的相遇</span></div></div><div class="hint-text">成就「异星知音」已解锁。<br>还有 ${4-state.relics.length} 件遗物等待发现；你随时可以回到任何区域。</div><div class="modal-actions" style="justify-content:center"><button class="secondary" id="ending-map">查看田野档案</button><button class="primary" id="ending-explore">继续这个世界</button></div></div>`,{large:true});$('#ending-explore').onclick=closeModal;$('#ending-map').onclick=openMap;}
function openMap(){closeObservation();modal(`<div class="panel-kicker">EXPEDITION ATLAS</div><h2>星图与田野档案</h2><p class="intro">理解一个文明，也包括它的日常、记忆与光。</p><div class="map-regions">${REGIONS.map((r,i)=>`<button class="map-region" data-map-region="${i}" ${i>state.unlocked?'disabled':''}><span>${state.completed.includes(i)?'✓':i>state.unlocked?'·':'0'+(i+1)}</span>${r.name}</button>`).join('')}</div><div class="section-label">考察成就 · ${ACHIEVEMENTS.filter(a=>achieved(a.id)).length} / 6</div><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<div class="achievement ${achieved(a.id)?'earned':''}"><span>${a.icon}</span><h3>${a.name}</h3><p>${a.desc}</p></div>`).join('')}</div><div class="section-label">延伸研究</div><div class="guide-grid"><div class="guide-card"><h3>会变动的「我」与「你」</h3><p>跟随说话者变化，分清两个最容易混淆的指代。</p><button class="validate-button" id="pronoun-game" ${state.verified.includes('ta')?'':'disabled'}>${state.pronouns?'重新挑战':state.verified.includes('ta')?'开始指代练习':'解读「你」后解锁'}</button></div><div class="guide-card"><h3>光的园丁</h3><p>调整反光板，让不同颜色的光同时抵达幼灯。</p><button class="validate-button" id="garden-game" ${state.completed.includes(2)?'':'disabled'}>${state.garden?'再次调光':state.completed.includes(2)?'培育随行活灯':'唤醒幼灯后解锁'}</button></div></div>${state.relics.length?`<div class="section-label">文明遗物 · ${state.relics.length} / 4</div>${state.relics.map(i=>`<div class="clue"><small>${REGIONS[i].secret}</small>${REGIONS[i].secretText}</div>`).join('')}`:''}<div class="modal-actions"><button class="secondary" id="map-settings">旅程设置</button><button class="primary" id="map-return">返回世界</button></div>`,{large:true});$$('[data-map-region]').forEach(b=>b.onclick=()=>travel(Number(b.dataset.mapRegion)));$('#pronoun-game').onclick=openPronouns;$('#garden-game').onclick=openGarden;$('#map-return').onclick=closeModal;$('#map-settings').onclick=openSettings;}
function openPronouns(){let round=0,score=0;const quiz=[{speaker:'青色居民',listener:'你（语言学家）',word:'na',correct:'青色居民'}, {speaker:'金色居民',listener:'青色居民',word:'ta',correct:'青色居民'}, {speaker:'你（语言学家）',listener:'金色居民',word:'na',correct:'你（语言学家）'}, {speaker:'青色居民',listener:'金色居民',word:'ta',correct:'金色居民'}];function render(){const q=quiz[round];modal(`<div class="panel-kicker">PRONOUN FIELD STUDY / 0${round+1}</div><h2>此刻，这个字指向谁？</h2><p class="intro">${q.speaker} 正在对 ${q.listener} 说话。</p><div class="utterance"><span class="rune">${getWord(q.word).glyph}</span></div><div class="section-label">记住：指代随着说话者改变</div><div class="sentence-bank">${['青色居民','金色居民','你（语言学家）'].map(v=>`<button class="secondary" data-person="${v}">${v}</button>`).join('')}</div><div class="feedback" id="pronoun-feedback"></div>`);$$('[data-person]').forEach(b=>b.onclick=()=>{if(b.dataset.person===q.correct){score++;tone(0,'success');if(++round<4)render();else{state.pronouns=true;save();modal(`<div class="panel-kicker">FIELD STUDY COMPLETE</div><h2>你跟上了每一次指向</h2><p class="intro">「我」总是说话者，「你」总是听者。它们不是一个人的名字，而是两个人之间的关系。</p><div class="hint-text">指代练习 ${score} / 4 完成。居民在你的田野手记上画下两个相向的手掌。</div><div class="modal-actions"><button class="primary" id="pronoun-done">收入研究手记</button></div>`);$('#pronoun-done').onclick=openMap}}else{$('#pronoun-feedback').textContent=q.word==='na'?'居民再次触碰自己的胸口。想想现在是谁在说话。':'居民的手掌朝向正在听他讲话的人。再跟随一次他的视线。';tone(0,'error')}})}render()}
function openGarden(){let amber=30,cyan=80;modal(`<div class="panel-kicker">LIVING LIGHT / OPTIONAL STUDY</div><h2>让幼灯找到舒适的光</h2><p class="intro">两片反光板共同决定幼灯接收的光。<br>石台标记写着：暖光是冷光的两倍，合计亮度为 90。</p><div class="utterance" style="height:105px"><span id="garden-bulb" style="font-size:61px;color:#b7cf9c;transition:filter .3s">⏣</span></div><label class="setting-row">暖色反光板 <input type="range" id="amber-light" min="0" max="90" step="10" value="30" aria-label="暖色光亮度"><strong id="amber-value">30</strong></label><label class="setting-row">冷色反光板 <input type="range" id="cyan-light" min="0" max="90" step="10" value="80" aria-label="冷色光亮度"><strong id="cyan-value">80</strong></label><div class="feedback" id="garden-feedback">幼灯微微收拢，亮度还不合适。</div><div class="modal-actions"><button class="secondary" id="garden-back">返回星图</button><button class="primary" id="garden-check">观察幼灯反应</button></div>`);$('#garden-back').onclick=openMap;$('#amber-light').oninput=e=>{amber=Number(e.target.value);$('#amber-value').textContent=amber;preview()};$('#cyan-light').oninput=e=>{cyan=Number(e.target.value);$('#cyan-value').textContent=cyan;preview()};function preview(){$('#garden-bulb').style.color=`hsl(${70+cyan},55%,${40+(amber+cyan)/7}%)`;$('#garden-bulb').style.filter=`drop-shadow(0 0 ${Math.max(3,16-Math.abs(90-amber-cyan)/4)}px #d4ea83)`};$('#garden-check').onclick=()=>{if(amber===60&&cyan===30){state.garden=true;save();tone(0,'success');$('#garden-feedback').textContent='幼灯完全舒展，发出温暖的金色辉光。成就解锁：光的园丁。';$('#garden-feedback').classList.add('success');if(world)world.companion.material.color.setHex(0xffd684);$('#garden-check').textContent='完成培育';$('#garden-check').onclick=openMap}else{$('#garden-feedback').textContent=amber+cyan!==90?`当前合计亮度为 ${amber+cyan}。幼灯需要刚好 90。`:'合计亮度合适了，但暖光还不是冷光的两倍。';tone(0,'error')}}}
function openHelp(){closeObservation();modal(`<div class="panel-kicker">A LINGUIST'S FIELD GUIDE</div><h2>先看见，再听懂</h2><p class="intro">你是第一个抵达这里的语言学家。居民愿意与你交流，但你们还没有共同的语言。</p><div class="guide-grid"><div class="guide-card"><span>01</span><h3>观察世界</h3><p>点击居民上方的观察标记，或靠近后按 E。每个符号都有两种行为语境。</p></div><div class="guide-card"><span>02</span><h3>记录与推断</h3><p>收集两条证据，在词典中提出词义假设。注意角色和物品改变后，什么仍然不变。</p></div><div class="guide-card"><span>03</span><h3>检验理解</h3><p>凑齐三个词的假设后，在新语境中验证。错误不会丢失进度，随时可以调整。</p></div><div class="guide-card"><span>04</span><h3>用语言行动</h3><p>组织正确的句子，与居民交流。获得信任、种子与活灯，最终打开月影之门。</p></div></div><p class="settings-info" style="margin-top:23px">WASD / 方向键移动 · 点击地面前往 · 拖动环视 · 滚轮缩放<br>E 观察 · J 打开词典 · Esc 关闭面板<br>手机上使用方向按钮移动，点击观察标记即可互动。<br>进度自动保存在当前浏览器。</p><div class="modal-actions"><button class="primary" id="help-close">继续探索</button></div>`,{large:true});$('#help-close').onclick=closeModal}
function openSettings(){modal(`<div class="panel-kicker">EXPEDITION SETTINGS</div><h2>旅程设置</h2><div class="setting-row"><div>环境音与语言音节<p>柔和的行星低鸣与合成音节</p></div><button class="secondary" id="settings-sound">${state.sound?'已开启':'已关闭'}</button></div><div class="setting-row"><div>本地田野档案<p>${saveAvailable?'当前浏览器自动保存进度':'浏览器存储不可用，关闭页面可能丢失进度'}</p></div><button class="secondary" id="export-save">导出存档</button></div><div class="setting-row"><div>开始一段新旅程<p>将清空这个浏览器里的现有进度</p></div><button class="secondary" id="reset-save">重新开始</button></div><p class="settings-info">已破译 ${state.verified.length}/12 个词语 · ${evidenceTotal()}/24 条证据<br>你可以从底部旅程栏返回已解锁的区域。</p><div class="modal-actions"><button class="primary" id="settings-close">返回世界</button></div>`);$('#settings-sound').onclick=()=>{toggleSound();$('#settings-sound').textContent=state.sound?'已开启':'已关闭'};$('#settings-close').onclick=closeModal;$('#export-save').onclick=()=>{const blob=new Blob([JSON.stringify({...state,elapsed:state.elapsed+(Date.now()-sessionStart)/1000},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='星语-田野档案.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('田野档案已导出')};$('#reset-save').onclick=()=>{modal(`<div class="panel-kicker">NEW EXPEDITION</div><h2>重新出发？</h2><p class="intro">这会清空当前浏览器中的词典、证据、遗物与章节进度。你可以先返回设置，导出存档留念。</p><div class="modal-actions"><button class="secondary" id="cancel-reset">保留旅程</button><button class="primary" id="confirm-reset">确认重新开始</button></div>`);$('#cancel-reset').onclick=openSettings;$('#confirm-reset').onclick=()=>{state=fresh();sessionStart=Date.now();ambient();closeModal();closeObservation();world?.buildRegion(0);updateUI();toast('新的旅程开始了。去看看井边的居民吧。')}}}
function toggleSound(){state.sound=!state.sound;ambient();updateUI();if(state.sound)tone(0)}
$('#sound-toggle').onclick=toggleSound;$('#help-button').innerHTML=ICONS.help;$('#help-button').onclick=openHelp;$('#settings-button').innerHTML=ICONS.settings;$('#settings-button').onclick=openSettings;$('#map-button').onclick=openMap;$('#focus-reset').onclick=()=>world?.resetCamera();$('#journal-toggle').onclick=()=>$('#journal').classList.toggle('open');$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderJournal()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').children.length)closeModal();else if(currentObservation)closeObservation();else $('#journal').classList.remove('open')}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='KeyJ'&&!$('#modal-root').children.length){$('#journal').classList.toggle('open');if(innerWidth>640){tab=tab==='words'?'evidence':'words';renderJournal()}}if(e.code==='KeyE'&&!$('#modal-root').children.length&&world?.nearby)observe(world.nearby);if(e.key==='Tab'&&$('#modal-root').children.length){const focusables=[...$('.modal').querySelectorAll('button:not(:disabled),input,select,a[href]')];const first=focusables[0],last=focusables.at(-1);if(!$('.modal').contains(document.activeElement)){e.preventDefault();first?.focus()}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('pointerdown',()=>{if(state.sound)ambient()},{once:true});window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){audioContext?.suspend();save()}else if(state.sound)audioContext?.resume()});
try{world=new World($('#world'),{onInteract:observe,onRelic:discoverRelic,onGate:openDialogue,onNearby:id=>{const el=$('#nearby');el.classList.toggle('hidden',!id);if(id)el.querySelector('span').textContent=getWord(id).site},onReady:()=>{$('#loading').style.opacity='0';setTimeout(()=>$('#loading').remove(),900);if(evidenceTotal()===0)setTimeout(()=>toast('点击居民上方的观察标记，开始你的第一份田野记录。'),900)}});if(state.region!==0)world.buildRegion(state.region)}catch(error){console.error('World initialization failed',error);$('#world-error').classList.remove('hidden');$('#loading').remove();}updateUI();
window.__LINGUA__={get state(){return JSON.parse(JSON.stringify(state))},get worldReady(){return !!world},get rendererInfo(){return world?{calls:world.renderer.info.render.calls,triangles:world.renderer.info.render.triangles}:null}};
